export const additionalScenarios: Scenario[] = drafts.map((draft, scenarioIndex) => ({
  id: draft.id,
  category: draft.category,
  title: draft.title,
  description: draft.description,
  options: optionIds.map((id, index) => ({ id, label: draft.choices[index] })),
  responses: draft.reasons.map((reasoning, index) => {
    const identity = identities[(scenarioIndex + index) % identities.length];
    return {
      id: `${draft.id}-${index}`,
      anonymousLabel: identity.name,
      selectedOption: optionIds[Math.floor(index / 2)],
      reasoning,
      tags: identity.tags,
      avatar: (scenarioIndex + index + 2) % identities.length,
    };
  }).sort((a, b) => (Number(a.id.split('-').pop()) * 5 % 8) - (Number(b.id.split('-').pop()) * 5 % 8)),
  insight: draft.insight,
}));